#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Verifies docs/infra/switch.md against the running switch (#30).
# Run on the DL380 G9 host OS; keep the switch web UI open on another machine.
# Read-only: it changes nothing on the switch or the host.

TOTAL_STAGES=9

GW_PREFIX="10.10"
SWITCH_URL="http://10.10.10.2"
REPORT="${REPORT:-switch-verify-$(date +%F).md}"
RAW=$(mktemp)
RESULTS=()
FAILED=0

# record PASS|FAIL "check" ["note"] adds one line to the result checklist.
record() {
  local mark="x"; [[ "$1" == PASS ]] || { mark=" "; FAILED=$((FAILED + 1)); }
  RESULTS+=("- [$mark] $2${3:+ — $3}")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else printf '  %s✗ %s%s\n' "$RED" "$2${3:+ ($3)}" "$RESET"; fi
}

# run CMD... shows a command and its output, and keeps both for the report.
run() {
  local out rc=0
  out=$("$@" 2>&1) || rc=$?
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  printf '%s\n' "$out" | sed 's/^/    /'
  printf '$ %s\n%s\n\n' "$*" "$out" >> "$RAW"
  return "$rc"
}

# check_ui "check" asks the human whether a web UI page matches the doc.
check_ui() {
  local diff=""
  if confirm "Does it match?"; then record PASS "$1"
  else ask diff "What differs?"; record FAIL "$1" "$diff"; fi
  pause
}

# find_addr "10.10.20." prints "<netns or -> <iface> <addr/cidr>" for every
# IPv4 address in that subnet, on the host and in network namespaces.
find_addr() {
  ip -o -4 addr show | awk -v p="$1" 'index($4, p) == 1 { print "-", $2, $4 }'
  local ns
  for ns in $(ip netns list 2>/dev/null | awk '{ print $1 }'); do
    sudo ip -n "$ns" -o -4 addr show 2>/dev/null \
      | awk -v p="$1" -v ns="$ns" 'index($4, p) == 1 { print ns, $2, $4 }'
  done
}

# ping_from NS ADDR TARGET pings TARGET from ADDR (inside NS unless "-").
ping_from() {
  if [[ "$1" == "-" ]]; then run ping -c 3 -W 1 -I "${2%/*}" "$3"
  else run sudo ip netns exec "$1" ping -c 3 -W 1 "$3"; fi
}

# neigh_of NS IFACE TARGET shows the ARP entry for TARGET (inside NS unless "-").
neigh_of() {
  if [[ "$1" == "-" ]]; then run ip neigh show to "$3" dev "$2"
  else run sudo ip -n "$1" neigh show to "$3" dev "$2"; fi
}

# check_vlan VLAN NIC: the VLAN has an address in its subnet, and its gateway
# is reachable across the switch from that address. The gateway's firewall may
# reject the ping (VLAN 20 and 30 by design), so the proof is that ARP resolved
# the gateway's MAC address, not that ping got an echo reply.
check_vlan() {
  local vlan="$1" nic="$2" prefix="$GW_PREFIX.$1." found ns iface addr out
  found=$(find_addr "$prefix")
  printf '$ addresses in %s0/24\n%s\n\n' "$prefix" "${found:-(none)}" >> "$RAW"
  if [[ -z "$found" ]]; then
    record FAIL "VLAN $vlan: an address in ${prefix}0/24" "none found on the host or in a netns"
    return
  fi
  read -r ns iface addr <<< "$(head -n1 <<< "$found")"
  if [[ "$ns" == "-" ]]; then say "Found $addr on $iface"
  else say "Found $addr on $iface (netns $ns)"; fi
  record PASS "VLAN $vlan: $iface has $addr (expected via $nic)"
  ping_from "$ns" "$addr" "${prefix}1" || note "No echo reply; the router firewall may reject ping on this VLAN."
  out=$(neigh_of "$ns" "$iface" "${prefix}1" || true)
  printf '%s\n' "$out"
  if grep -q lladdr <<< "$out"; then
    record PASS "VLAN $vlan: gateway ${prefix}1 reachable (ARP resolved its MAC)"
  else
    record FAIL "VLAN $vlan: gateway ${prefix}1 reachable" "ARP did not resolve"
  fi
}

banner "Switch verification (#30)"

stage "Before you start"
say "This checks docs/infra/switch.md against the running switch."
say "Run it on the DL380 G9 host OS. Keep the switch web UI open elsewhere."
step "On a machine on VLAN 10 or the tailnet, open $SWITCH_URL and log in."
open_url "$SWITCH_URL"
step "Homepage → Port Info: set Port 15 Status to Disabled, then Save."
note "The report is written to $REPORT in this directory."
pause "Done? Press Enter"

stage "Web UI: VLAN Members"
step "VLAN Settings → VLAN Members."
say "Expected: VLAN Settings on; VLAN IDs 1, 10, 20, 30 and nothing else."
check_ui "VLAN Members lists 1, 10, 20, 30"

stage "Web UI: port VLANs"
step "VLAN Settings → VLAN Settings, and compare with the Ports table in switch.md."
say "Expected:"
note "  Port 2, 14     Access  permit 10  native 10"
note "  Port 4         Access  permit 10  native 10"
note "  Port 6, 12     Access  permit 20  native 20"
note "  Port 8         Access  permit 30  native 30"
note "  Port 15, 16    Trunk   permit 1,10,20,30  native 1"
note "  Other ports    Access  permit 1   native 1"
check_ui "Port modes, permitted and native VLANs match switch.md"

stage "Web UI: management IP"
step "System Settings → IP Settings."
say "Expected: VLAN 10, Auto Obtain IP disabled, IP 10.10.10.2, mask 255.255.255.0,"
say "gateway 10.10.10.1, DNS 10.10.10.1."
check_ui "Management IP is 10.10.10.2/24 on VLAN 10"

stage "Web UI: port status"
step "Homepage → Port Info → Refresh List."
say "Expected: ports 2, 4, 6, 8, 16 Enabled and connected; every other port Disabled"
say "(port 15 included). Known issue: 2/4/6/8 at 100M, 16 at 1000M."
check_ui "Only ports 2, 4, 6, 8, 16 are enabled, and all five are up"

stage "Host NICs"
say "Link state, speed and bridge membership of the cabled NICs."
run ip -br link show || true
for nic in eno1 eno2 eno3; do
  if [[ -e /sys/class/net/$nic ]]; then
    state=$(cat "/sys/class/net/$nic/operstate")
    speed=$(cat "/sys/class/net/$nic/speed" 2>/dev/null || echo "?")
    printf '$ %s operstate/speed\n%s %sMb/s\n\n' "$nic" "$state" "$speed" >> "$RAW"
    if [[ "$state" == up ]]; then record PASS "$nic is up ($speed Mb/s)"
    else record FAIL "$nic is up" "operstate $state"; fi
  else
    record FAIL "$nic exists" "no such interface"
  fi
done
pause

stage "VLAN 10 · MGMT"
check_vlan 10 eno1
for target in 10.10.10.2 10.10.10.10; do
  if run ping -c 3 -W 1 "$target"; then record PASS "VLAN 10: $target answers"
  else record FAIL "VLAN 10: $target answers"; fi
done
if run curl -s -o /dev/null -w '%{http_code}\n' --max-time 5 "$SWITCH_URL"; then
  record PASS "VLAN 10: switch web UI answers on :80"
else
  record FAIL "VLAN 10: switch web UI answers on :80"
fi
pause

stage "VLAN 20 · SERVICES"
check_vlan 20 eno2
pause

stage "VLAN 30 · WORKLOAD"
note "The address may live on a Neutron bridge or in a qrouter namespace (needs sudo)."
check_vlan 30 eno3
pause

{
  printf '## Switch verification — %s\n\n' "$(date '+%F %H:%M')"
  printf 'Run on `%s` against `docs/infra/switch.md`.\n\n' "$(hostname)"
  printf '%s\n' "${RESULTS[@]}"
  printf '\n<details><summary>Command output</summary>\n\n```\n'
  cat "$RAW"
  printf '```\n\n</details>\n'
} > "$REPORT"
rm -f "$RAW"

finish
if (( FAILED )); then warn "$FAILED check(s) failed; see $REPORT"
else note "All checks passed."; fi
note "Paste $REPORT as a comment on issue #30."
printf '\n'
